-- Performance hardening and foreign-key indexes (remote version 20261114083710).
drop policy products_update_creator on public.marketplace_products;
drop policy products_update_admin on public.marketplace_products;
create policy products_update_owner_or_admin on public.marketplace_products for update to authenticated
using (creator_id = (select auth.uid()) or (select auth.jwt()) -> 'app_metadata' ->> 'role' = 'admin')
with check ((select auth.jwt()) -> 'app_metadata' ->> 'role' = 'admin' or (creator_id = (select auth.uid()) and status in ('draft','in_review','rejected')));
alter policy listings_select_own on public.listings using ((select auth.uid()) = user_id);
alter policy listings_insert_own on public.listings with check ((select auth.uid()) = user_id);
alter policy listings_update_own on public.listings using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
alter policy listings_delete_own on public.listings using ((select auth.uid()) = user_id);
alter policy profiles_select_self_or_admin on public.profiles using ((select auth.uid()) = id or ((select auth.jwt()) -> 'app_metadata' ->> 'role') = 'admin');
alter policy profiles_insert_self on public.profiles with check ((select auth.uid()) = id);
alter policy profiles_update_self on public.profiles using ((select auth.uid()) = id) with check ((select auth.uid()) = id);
alter policy creator_profiles_public_read on public.creator_profiles using (is_public or (select auth.uid()) = user_id or ((select auth.jwt()) -> 'app_metadata' ->> 'role') = 'admin');
alter policy creator_profiles_insert_self on public.creator_profiles with check ((select auth.uid()) = user_id);
alter policy creator_profiles_update_self on public.creator_profiles using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
alter policy products_public_read on public.marketplace_products using (status='published' or creator_id=(select auth.uid()) or ((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin');
alter policy products_insert_creator on public.marketplace_products with check (creator_id=(select auth.uid()) and status='draft');
alter policy product_versions_read on public.product_versions using (exists(select 1 from public.marketplace_products p where p.id=product_id and (p.status='published' or p.creator_id=(select auth.uid()) or ((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin')));
alter policy product_versions_insert_creator on public.product_versions with check (created_by=(select auth.uid()) and verification_state='documented' and exists(select 1 from public.marketplace_products p where p.id=product_id and p.creator_id=(select auth.uid())));
alter policy submissions_read_owner_or_admin on public.review_submissions using (submitted_by=(select auth.uid()) or ((select auth.jwt()) -> 'app_metadata' ->> 'role') in ('admin','reviewer'));
alter policy submissions_insert_owner on public.review_submissions with check (submitted_by=(select auth.uid()) and status='pending' and reviewer_id is null and exists(select 1 from public.marketplace_products p where p.id=product_id and p.creator_id=(select auth.uid())));
alter policy submissions_update_admin on public.review_submissions using (((select auth.jwt()) -> 'app_metadata' ->> 'role') in ('admin','reviewer')) with check (((select auth.jwt()) -> 'app_metadata' ->> 'role') in ('admin','reviewer'));
alter policy review_events_admin_read on public.review_events using (((select auth.jwt()) -> 'app_metadata' ->> 'role') in ('admin','reviewer'));
alter policy review_events_admin_insert on public.review_events with check (((select auth.jwt()) -> 'app_metadata' ->> 'role') in ('admin','reviewer'));
alter policy commission_rules_admin_all on public.commission_rules using (((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin') with check (((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin');
alter policy purchases_buyer_read on public.purchases using (buyer_id=(select auth.uid()) or ((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin');
alter policy purchase_items_buyer_or_creator_read on public.purchase_items using (exists(select 1 from public.purchases p where p.id=purchase_id and p.buyer_id=(select auth.uid())) or creator_id=(select auth.uid()) or ((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin');
alter policy ledger_owner_read on public.ledger_entries using (user_id=(select auth.uid()) or ((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin');
alter policy payout_accounts_owner_read on public.payout_accounts using (user_id=(select auth.uid()) or ((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin');
alter policy payout_accounts_owner_insert on public.payout_accounts with check (user_id=(select auth.uid()) and status='pending');
alter policy payout_requests_owner_read on public.payout_requests using (user_id=(select auth.uid()) or ((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin');
alter policy payout_requests_owner_insert on public.payout_requests with check (user_id=(select auth.uid()) and status='requested');
alter policy product_reviews_public_read on public.product_reviews using (status='published' or buyer_id=(select auth.uid()) or ((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin');
alter policy product_reviews_buyer_insert on public.product_reviews with check (buyer_id=(select auth.uid()) and status='pending' and exists(select 1 from public.purchase_items pi join public.purchases pu on pu.id=pi.purchase_id where pi.id=purchase_item_id and pi.product_id=product_id and pu.buyer_id=(select auth.uid()) and pu.status='paid'));
alter policy support_tickets_requester_read on public.support_tickets using (requester_id=(select auth.uid()) or ((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin');
alter policy support_tickets_requester_insert on public.support_tickets with check (requester_id=(select auth.uid()));
alter policy support_tickets_admin_update on public.support_tickets using (((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin') with check (((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin');
alter policy referral_codes_owner_read on public.referral_codes using (owner_id=(select auth.uid()) or ((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin');
alter policy referral_codes_owner_insert on public.referral_codes with check (owner_id=(select auth.uid()));
alter policy campaign_attributions_admin_read on public.campaign_attributions using (((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin');
alter policy app_config_public_read on public.app_config using (is_public or ((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin');
alter policy app_config_admin_insert on public.app_config with check (((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin');
alter policy app_config_admin_update on public.app_config using (((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin') with check (((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin');
alter policy app_config_admin_delete on public.app_config using (((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin');
alter policy audit_logs_admin_read on public.audit_logs using (((select auth.jwt()) -> 'app_metadata' ->> 'role')='admin');
